  // Mật khẩu trang admin.html — BẮT BUỘC để gọi chế độ soạn đề (generate_test). Phải trùng ADMIN_PASSWORD trong admin.html.
  // Để rỗng = không kiểm tra (không khuyến nghị: ai cũng soạn đề được và tốn token).
  generateKey: 'nhat1234',

  // Các chế độ gọi AI. Prompt của từng chế độ nằm trong node "Chat Gate" (phía server).
  modes: {
    feedback:      { maxTokens: 6543, perUserPerDay: 30 },                              // nhận xét cá nhân hoá sau khi học sinh làm xong
    generate_test: { maxTokens: 8000, perUserPerDay: 300, requireAdminSecret: true }     // soạn đề (admin) — tạo hàng loạt nên cho nhiều lượt
  },

  tokenTtlSec: 300,          // tuổi thọ token (60–900)
  tokenIssuePerHour: 40,     // số token tối đa/người dùng/web/giờ
  perUserPerMin: 8,          // số câu hỏi/người dùng/phút
  perUserPerDay: 80,         // số câu hỏi/người dùng/ngày
  dailyRequestCap: 1500,     // TRẦN số câu hỏi toàn hệ thống/ngày
  dailyTokenCap: 1000000,     // TRẦN token LLM toàn hệ thống/ngày  → chỉnh theo ngân sách
  perSiteDailyRequestCap: 0, // trần câu hỏi/ngày cho MỖI web con (0 = không giới hạn riêng)
  perSiteDailyTokenCap: 0,   // trần token/ngày cho MỖI web con (0 = không giới hạn riêng)
  ipMaxPerMinToken: 30,      // lớp chặn thô theo IP
  ipMaxPerMinChat: 60,

  models: ['gpt-4.1-mini-2025-04-14', 'gpt-4o-mini', 'gpt-5-mini'],  // thử lần lượt khi model trước lỗi 5xx

  logKeep: 300               // số dòng log gần nhất giữ lại trong n8n
};
// =========================================================

const item = $input.first().json;
let route = '';
const u = String(item.webhookUrl || '');
if (u.includes('acdi-gw-token')) route = 'token';
else if (u.includes('acdi-gw-chat')) route = 'chat';
else if (u.includes('acdi-gw-admin')) route = 'admin';
if (!route) {
  try {
    if ($('Webhook Token').isExecuted) route = 'token';
    else if ($('Webhook Chat').isExecuted) route = 'chat';
    else if ($('Webhook Admin').isExecuted) route = 'admin';
  } catch (e) { /* bỏ qua */ }
}
return [{ json: { route, cfg, req: item } }];

const C = $('Config').first().json;
const cfg = C.cfg, req = C.req || {};
function parseBody(r) {
  let b = r && r.body;
  if (b && typeof b === 'object' && typeof b.data === 'string' && Object.keys(b).length === 1) b = b.data;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
  return (b && typeof b === 'object' && !Array.isArray(b)) ? b : {};
}
const body = parseBody(req);
const headers = req.headers || {};
const rawOrigin = String(headers.origin || '').slice(0, 200);
const refOrigin = ((/^(https?:\/\/[^\/?#]+)/.exec(String(headers.referer || headers.referrer || '')) || [])[1] || '').slice(0, 200);
// Nếu proxy của hosting đổi/xóa Origin, dùng origin lấy từ Referer (trình duyệt tự gắn, JS không giả được)
let origin = rawOrigin;
if (!cfg.allowedOrigins.includes(origin) && cfg.allowedOrigins.includes(refOrigin)) origin = refOrigin;
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown').split(',')[0].trim().slice(0, 64);
const corsOrigin = cfg.allowedOrigins.includes(origin) ? origin : '';

// Xác định "web con" gọi AI: domain + thư mục đầu tiên của page_url (vd. tiepbuoc.github.io/Pop-AI).
// Origin do trình duyệt tự gắn nên đáng tin; page_url do web tự khai nên chỉ để ghi nhận.
function where(origin, pageUrl) {
  const host = origin.replace(/^https?:\/\//, '') || 'unknown';
  const m = /^(https?:\/\/[^\/?#]+)(\/[^?#]*)?/.exec(String(pageUrl || ''));
  if (!m || m[1] !== origin) return { site: (host + '/?').slice(0, 100), page: '' };
  const path = m[2] || '/';
  const seg = path.split('/').filter(Boolean)[0] || '';
  return { site: (host + (seg ? '/' + seg : '')).slice(0, 100), page: (m[1] + path).slice(0, 200) };
}
const loc = where(origin, typeof body.page_url === 'string' ? body.page_url.slice(0, 300) : '');

function fail(status, error, reason, log = true) {
  return [{ json: { ok: false, status, body: { error }, corsOrigin,
    _log: log ? { endpoint: 'token', site: loc.site, page: loc.page, uid: '', status, reason, origin, rawOrigin, refOrigin, ip } : null } }];
}

const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.ipHitsT = sd.ipHitsT || {};
const hits = (sd.ipHitsT[ip] || []).filter(t => now - t < 60000);
hits.push(now);
sd.ipHitsT[ip] = hits;
const ks = Object.keys(sd.ipHitsT);
if (ks.length > 3000) for (const k of ks) { if (!sd.ipHitsT[k].some(t => now - t < 60000)) delete sd.ipHitsT[k]; }
if (hits.length > cfg.ipMaxPerMinToken) return fail(429, 'too_many_requests', 'ip_rate_limit', false);

if (!cfg.allowedOrigins.includes(origin)) return fail(403, 'forbidden', 'origin_not_allowed');
if (!cfg.enabled || sd.disabled === true) return fail(503, 'gateway_disabled', 'kill_switch');
if (cfg.blockedSites.includes(loc.site)) return fail(403, 'forbidden', 'site_blocked');
if (typeof body.id_token !== 'string' || body.id_token.length < 20 || body.id_token.length > 4096) return fail(400, 'bad_request', 'bad_id_token_format');

return [{ json: { ok: true, idToken: body.id_token, loc, origin, ip, corsOrigin } }];

const crypto = require('crypto');
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const cfg = $('Config').first().json.cfg;
const p = $('Token Parse').first().json;
const lk = $('Verify ID Token').first().json;

function result(status, body, reason, uid) {
  return [{ json: { ok: status === 200, status, body, corsOrigin: p.corsOrigin,
    _log: { endpoint: 'token', site: p.loc.site, page: p.loc.page, uid: uid || '', status, reason, origin: p.origin, ip: p.ip } } }];
}

// 1) Firebase ID token phải hợp lệ (xác minh qua Firebase Auth, không đụng Firestore)
const user = (lk.statusCode === 200 && lk.body && Array.isArray(lk.body.users)) ? lk.body.users[0] : null;
if (!user || !user.localId) return result(401, { error: 'invalid_id_token' }, 'invalid_id_token');
if (user.disabled === true) return result(403, { error: 'forbidden' }, 'user_disabled', user.localId);
const uid = String(user.localId);

// 2) Giới hạn số token cấp / giờ / người dùng / web
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.issued = sd.issued || {};
const key = p.loc.site + ':' + uid;
const arr = (sd.issued[key] || []).filter(t => now - t < 3600000);
if (arr.length >= num(cfg.tokenIssuePerHour, 40)) return result(429, { error: 'too_many_requests' }, 'token_issue_limit', uid);
arr.push(now);
sd.issued[key] = arr;
const ks = Object.keys(sd.issued);
if (ks.length > 3000) for (const k of ks) { if (!sd.issued[k].some(t => now - t < 3600000)) delete sd.issued[k]; }

// 3) Khoá ký token: tự sinh ở lần chạy đầu và lưu trong n8n (không nằm trong code, không cần cấu hình tay)
if (typeof sd.jwtSecret !== 'string' || sd.jwtSecret.length < 32) sd.jwtSecret = crypto.randomBytes(32).toString('hex');

// 4) Ký token HS256
const ttl = Math.min(900, Math.max(60, num(cfg.tokenTtlSec, 300)));
const iat = Math.floor(now / 1000);
const payload = { iss: 'acdi-gw', site: p.loc.site, uid, iat, exp: iat + ttl, jti: crypto.randomBytes(8).toString('hex') };
const b64u = o => Buffer.from(typeof o === 'string' ? o : JSON.stringify(o)).toString('base64url');
const head = b64u({ alg: 'HS256', typ: 'JWT' });
const pay = b64u(payload);
const sig = crypto.createHmac('sha256', sd.jwtSecret).update(head + '.' + pay).digest('base64url');

return result(200, { token: head + '.' + pay + '.' + sig, expires_in: ttl }, 'issued', uid);

const crypto = require('crypto');
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const C = $('Config').first().json;
const cfg = C.cfg, req = C.req || {};
function parseBody(r) {
  let b = r && r.body;
  if (b && typeof b === 'object' && typeof b.data === 'string' && Object.keys(b).length === 1) b = b.data;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
  return (b && typeof b === 'object' && !Array.isArray(b)) ? b : {};
}
const body = parseBody(req);
const headers = req.headers || {};
const rawOrigin = String(headers.origin || '').slice(0, 200);
const refOrigin = ((/^(https?:\/\/[^\/?#]+)/.exec(String(headers.referer || headers.referrer || '')) || [])[1] || '').slice(0, 200);
// Nếu proxy của hosting đổi/xóa Origin, dùng origin lấy từ Referer (trình duyệt tự gắn, JS không giả được)
let origin = rawOrigin;
if (!cfg.allowedOrigins.includes(origin) && cfg.allowedOrigins.includes(refOrigin)) origin = refOrigin;
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown').split(',')[0].trim().slice(0, 64);
const corsOrigin = cfg.allowedOrigins.includes(origin) ? origin : '';
const t0 = Date.now();

function pageOf(origin, pageUrl) {
  const m = /^(https?:\/\/[^\/?#]+)(\/[^?#]*)?/.exec(String(pageUrl || ''));
  return (m && m[1] === origin) ? (m[1] + (m[2] || '/')).slice(0, 200) : '';
}
const page = pageOf(origin, typeof body.page_url === 'string' ? body.page_url.slice(0, 300) : '');

// Web con lấy từ token do n8n ký (đáng tin hơn page_url); đọc tạm trước khi xác thực chỉ để ghi log từ chối
let site = '';
try { site = String(JSON.parse(Buffer.from(String(body.token || '').split('.')[1], 'base64url').toString('utf8')).site || '').slice(0, 100); } catch (e) { site = ''; }

function fail(status, error, reason, uid, log = true) {
  return [{ json: { ok: false, status, body: { error }, corsOrigin,
    _log: log ? { endpoint: 'chat', site, page, uid: uid || '', status, reason, origin, rawOrigin, refOrigin, ip, msgLen: String(body.message || '').length } : null } }];
}

// ---- 0) Giới hạn thô theo IP ----
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.ipHitsC = sd.ipHitsC || {};
const hits = (sd.ipHitsC[ip] || []).filter(t => now - t < 60000);
hits.push(now);
sd.ipHitsC[ip] = hits;
const iks = Object.keys(sd.ipHitsC);
if (iks.length > 3000) for (const k of iks) { if (!sd.ipHitsC[k].some(t => now - t < 60000)) delete sd.ipHitsC[k]; }
if (hits.length > cfg.ipMaxPerMinChat) return fail(429, 'too_many_requests', 'ip_rate_limit', '', false);

// ---- 1) Origin, công tắc, web bị chặn ----
if (!cfg.allowedOrigins.includes(origin)) return fail(403, 'forbidden', 'origin_not_allowed');
if (!cfg.enabled || sd.disabled === true) return fail(503, 'gateway_disabled', 'kill_switch');
if (typeof body.token !== 'string' || body.token.length < 20 || body.token.length > 2000) return fail(401, 'invalid_token', 'missing_token');
if (typeof sd.jwtSecret !== 'string' || sd.jwtSecret.length < 32) return fail(401, 'invalid_token', 'no_secret_yet');

// ---- 2) Xác thực token (HS256) ----
const parts = body.token.split('.');
if (parts.length !== 3) return fail(401, 'invalid_token', 'malformed_token');
let hdr, pl;
try {
  hdr = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
  pl = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
} catch (e) { return fail(401, 'invalid_token', 'malformed_token'); }
if (!hdr || hdr.alg !== 'HS256') return fail(401, 'invalid_token', 'bad_alg');
const expected = crypto.createHmac('sha256', sd.jwtSecret).update(parts[0] + '.' + parts[1]).digest();
let given;
try { given = Buffer.from(parts[2], 'base64url'); } catch (e) { given = Buffer.alloc(0); }
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return fail(401, 'invalid_token', 'bad_signature');
if (pl.iss !== 'acdi-gw' || typeof pl.site !== 'string' || !pl.site || typeof pl.uid !== 'string' || !pl.uid) return fail(401, 'invalid_token', 'bad_claims');
site = pl.site.slice(0, 100);
if (typeof pl.exp !== 'number' || pl.exp * 1000 <= Date.now()) return fail(401, 'token_expired', 'token_expired', pl.uid);
const uid = pl.uid;
if (cfg.blockedSites.includes(site)) return fail(403, 'forbidden', 'site_blocked', uid);

// ---- 3) Kiểm tra nội dung & dựng prompt (prompt do SERVER quyết định) ----
const MODES = (cfg.modes && typeof cfg.modes === 'object') ? cfg.modes : {};
const mode = typeof body.mode === 'string' ? body.mode : '';
if (!Object.prototype.hasOwnProperty.call(MODES, mode)) return fail(400, 'bad_request', 'unknown_mode', uid);
const mc = MODES[mode] || {};

// Chế độ soạn đề: cần mật khẩu admin (kiểm tra ở server, không chỉ ở trình duyệt)
if (mc.requireAdminSecret && String(cfg.generateKey || '').length >= 4) {
  const sha = s => crypto.createHash('sha256').update(String(s)).digest();
  if (!crypto.timingSafeEqual(sha(typeof body.admin_secret === 'string' ? body.admin_secret : ''), sha(cfg.generateKey))) return fail(403, 'forbidden', 'bad_admin_secret', uid);
}

const P = (body.params && typeof body.params === 'object' && !Array.isArray(body.params)) ? body.params : null;
if (!P) return fail(400, 'bad_request', 'bad_params', uid);
const str = (v, max) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const numIn = (v, lo, hi) => (typeof v === 'number' && isFinite(v) && v >= lo && v <= hi) ? v : null;
const schoolLevel = P.schoolLevel === 'thpt' ? 'thpt' : 'thcs';
const grade = str(String(P.grade == null ? '' : P.grade), 10);
if (!/^[0-9A-Za-z]{1,10}$/.test(grade)) return fail(400, 'bad_request', 'bad_grade', uid);

const LEVEL_INFO = {
  1: { title: 'Sử dụng AI có kiểm soát' },
  2: { title: 'Có dấu hiệu dựa vào AI' },
  3: { title: 'Lệ thuộc AI' },
  4: { title: 'Nguy cơ lệ thuộc AI cao' },
};
const SUBJECT_LABELS = { math: 'Toán', physics: 'Lý', chemistry: 'Hóa', literature: 'Văn', english: 'Anh', other: 'Môn khác' };

function essayFitLabel(score) {
  const s = Number(score);
  if (!Number.isFinite(s)) return 'chưa có dữ liệu';
  if (s <= 20) return 'rất phù hợp, thể hiện khả năng tự lập luận tốt';
  if (s <= 40) return 'khá phù hợp, còn vài chỗ có thể tự lập luận thêm';
  if (s <= 65) return 'có phần hạn chế, còn dựa khá nhiều vào gợi ý sẵn có';
  if (s <= 85) return 'hạn chế rõ, thiếu ý chính/lập luận của riêng mình';
  return 'chưa phù hợp, gần như chưa thể hiện được tư duy độc lập';
}
function scenarioCategoryLabel(title) {
  return String(title || '').replace(/^Tình huống\s*\d+\s*[·.\-–]?\s*/i, '').trim() || 'Tình huống tự luận';
}

const GEN_TEMPLATE = (criteria) => `Bạn là chuyên gia thiết kế công cụ đo lường tâm lý giáo dục, được giao soạn MỘT bộ đề ACDI Check
(đo Chỉ số lệ thuộc nhận thức vào AI của học sinh) phù hợp với nhóm đối tượng sau:
- Cấp học: ${criteria.schoolLevel === "thpt" ? "Trung học phổ thông (THPT)" : "Trung học cơ sở (THCS)"}
- Khối lớp: ${criteria.grade}
- Môn học thường dùng AI: ${(criteria.subjects || []).join(", ") || "không rõ"}

YÊU CẦU BẮT BUỘC — áp dụng GIỐNG NHAU cho MỌI lần soạn đề, không tự thay đổi cấu trúc hay cách hiểu:

1. Soạn đúng 5 NHÓM CHỈ BÁO theo đúng 5 khoá "key" và Ý NGHĨA ĐO LƯỜNG cố định sau (giữ nguyên
   key, được tự viết lại title/desc/câu hỏi cho phù hợp lứa tuổi và môn học nêu trên):
   - "start" (Phụ thuộc khi bắt đầu nhiệm vụ): mức độ cần AI để xác định cách làm/khởi động nhiệm vụ.
   - "idea" (Phụ thuộc về ý tưởng): khả năng tự hình thành ý tưởng, dàn ý, phương án giải quyết.
   - "process" (Phụ thuộc trong xử lí nhiệm vụ): mức độ giao cho AI phân tích, lập luận, hoàn thành sản phẩm.
   - "trust" (Phụ thuộc vào kết quả của AI): mức độ tin tưởng, chấp nhận câu trả lời AI mà không kiểm tra.
   - "independence" (Khả năng hoạt động khi không có AI): khả năng ghi nhớ, giải thích, tự hoàn thành khi không có AI.
   BẮT BUỘC soạn ĐỦ 25 câu (5 nhóm × 5 câu), TOÀN BỘ do bạn tự viết — không được bỏ trống hay rút gọn.
   PHÂN BỐ NỘI DUNG ĐỀU trong từng nhóm: 5 câu của MỘT nhóm phải đo 5 KHÍA CẠNH KHÁC NHAU của cùng
   một chỉ báo (không được viết 5 câu gần như lặp lại cùng một ý), để điểm trung bình của nhóm phản
   ánh đúng nhiều mặt của hành vi, không bị lệch vì phần lớn câu hỏi trùng ý nhau.
2. Mỗi nhóm có đúng 5 câu hỏi kiểu Likert 5 mức (từ "Hoàn toàn không đúng" đến "Hoàn toàn đúng"),
   mỗi câu có "id" duy nhất dạng "g{số nhóm 1-5}q{số câu 1-5}" (ví dụ g1q1..g1q5, g2q1..g2q5,...).
3. Trường "reverse" — ĐÂY LÀ CHỖ DỄ SAI NHẤT, PHẢI TỰ KIỂM TRA LẠI TỪNG CÂU TRƯỚC KHI TRẢ VỀ:
   - Mặc định "reverse: false" cho 4 nhóm đầu ("start","idea","process","trust") — NGHĨA LÀ mọi câu
     hỏi trong 4 nhóm này BẮT BUỘC phải viết theo hướng "câu đồng ý (chọn mức cao) = lệ thuộc AI
     NHIỀU HƠN". TUYỆT ĐỐI KHÔNG được viết một câu theo hướng ngược lại (ví dụ ca ngợi sự độc lập,
     "tôi tự nghĩ ra ý tưởng trước khi hỏi AI") rồi vẫn để reverse:false — làm vậy học sinh trả lời
     tốt (độc lập) sẽ bị chấm nhầm thành lệ thuộc cao, khiến điểm nhóm đó luôn bị đẩy lên rất cao
     một cách SAI LỆCH. Nếu bạn thấy một câu tự nhiên phải viết theo hướng độc lập, hãy VIẾT LẠI câu
     đó theo hướng lệ thuộc (ví dụ đổi thành "tôi khó tự nghĩ ra ý tưởng nếu chưa hỏi AI") thay vì đặt
     reverse:true cho nhóm này.
   - "reverse: true" CHỈ dùng cho TẤT CẢ 5 câu của nhóm "independence" (vì nhóm này đo năng lực độc
     lập, Likert càng cao thì càng ÍT lệ thuộc).
   - Trước khi trả JSON, tự rà soát: với mỗi câu reverse:false, "chọn mức 5 (Hoàn toàn đúng)" có
     đúng nghĩa là "lệ thuộc AI nhiều nhất" không? Nếu không đúng, phải sửa lại cách diễn đạt câu đó.
